package com.example.resilience;

import io.github.resilience4j.bulkhead.annotation.Bulkhead;
import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;
import io.github.resilience4j.retry.annotation.Retry;
import io.github.resilience4j.timelimiter.annotation.TimeLimiter;
import org.springframework.stereotype.Service;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CompletableFuture;

@Service
public class PaymentServiceClient {

    @CircuitBreaker(name = "paymentService", fallbackMethod = "fallbackGetPayments")
    @Bulkhead(name = "paymentService", type = Bulkhead.Type.THREADPOOL)
    @Retry(name = "paymentService")
    @TimeLimiter(name = "paymentService")
    public CompletableFuture<List<String>> fetchUserPayments(String userId) {
        return CompletableFuture.supplyAsync(() -> {
            // Simulated network call to an external payment gateway
            return externalPaymentApiCall(userId);
        });
    }

    private CompletableFuture<List<String>> fallbackGetPayments(String userId, Throwable t) {
        // Fallback must return the exact same return type (wrapped in CompletableFuture for TimeLimiter)
        return CompletableFuture.completedFuture(Collections.singletonList("DEFAULT_CACHED_PAYMENT"));
    }

    private List<String> externalPaymentApiCall(String userId) {
        // Implementation details of remote HTTP call
        return List.of("PAYMENT_1", "PAYMENT_2");
    }
}
